app.get("/hello", (req, res) => {
    const name = req.query.name;
    const escapeHtml = (value) =>
        String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/\"/g, "&quot;")
            .replace(/'/g, "&#39;")
            .replace(/`/g, "&#96;");

    res.send("<h1>Hello " + escapeHtml(name) + "</h1>");
});
